window.docContents[253].resolve({"/Typeclasses/#Logical-Foundations--Typeclasses--TODO":{"contents":"\n\n\n\n#check decidable_of_bool\n\nexample {P : Prop} (b : Bool) (h : b = true ↔ P) : Decidable P := by\n  by_cases hb : b\n  · apply isTrue\n    simp [← h, hb]\n  · apply isFalse\n    simp [← h, hb]\n\n\n#check decide_eq_false_iff_not\n#check decide_eq_true_iff\n\n\n\n\nexample {α β : Type} (a : α) [BEq α] [LawfulBEq α] (xs : List α) (neq : xs.filter (a == ·) ≠ []) : a ∈ xs := by\n  sorry\n\n\n\n\nend Reflection\n\n\n","context":"Logical Foundations\u0009Typeclasses","header":"11.7. TODO","id":"/Typeclasses/#Logical-Foundations--Typeclasses--TODO"}});